		for _, occ := range invalidated {
			occ.active = true
			occ.invalidTime = 0
			occ.invalidReason = ""
			occ.invalidOpID = ""
		}
		st.invalRecords = st.invalRecords[:invalLenBefore]
		delete(st.invalIndex, req.ID)
		return InvalidationResult{}, err
	}
