				Observations: []Observation{{ID: "L1", X: 0, Y: 0}}, // (4,4)，与 (4,3) 距离恰为 1
			},
		},
	}
	res, err := m.ImportSegment(seg)
	if err != nil {
		t.Fatalf("ImportSegment: %v", err)
	}

